**shutdown 实现**: 必须清理所有资源
```c
static int my_shutdown(FAR struct audio_lowerhalf_s *dev)
{
  FAR struct my_audio_driver_s *priv = (FAR struct my_audio_driver_s *)dev;
  FAR struct ap_buffer_s *buf;

  // 1. 停止硬件（防止新中断）
  disable_dma(priv);
  disable_codec(priv);

  // 2. 归还所有未完成的 buffer
  while (true)
    {
      flags = spin_lock_irqsave(&priv->lock);
      buf = list_remove_head(&priv->pending);
      spin_unlock_irqrestore(&priv->lock, flags);

      if (buf == NULL)
        {
          break;
        }

      // ⚠️ 在锁外回调（避免死锁）
      priv->dev.upper(priv->dev.priv,
                      AUDIO_CALLBACK_DEQUEUE,
                      buf, -ECANCELED);  // 使用错误状态
    }

  // 3. 重置驱动状态
  flags = spin_lock_irqsave(&priv->lock);
  priv->is_running = false;
  priv->pending_count = 0;
  spin_unlock_irqrestore(&priv->lock, flags);

  return OK;
}
```

**错误路径处理**:
```c
static int my_start(FAR struct audio_lowerhalf_s *dev)
{
  FAR struct my_audio_driver_s *priv = (FAR struct my_audio_driver_s *)dev;
  int ret;

  // 配置硬件
  ret = configure_codec(priv);
  if (ret < 0)
    {
      auderr("Configure codec failed: %d\n", ret);
      goto errout;
    }

  ret = enable_dma(priv);
  if (ret < 0)
    {
      auderr("Enable DMA failed: %d\n", ret);
      goto errout_codec;  // 回退到已配置的状态
    }

  flags = spin_lock_irqsave(&priv->lock);
  priv->is_running = true;
